"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3046],{19180:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"TeleportPad","desc":"Watcher for the `TeleportPad` tag: a `BasePart` that requests a teleport\\nwhen the local player walks onto it.\\n\\nRegistered by [CollectionWatcherController] at boot. Tag a part, give it a\\n`Node` string attribute naming the destination, and it works.\\n\\nOn touch the watcher dispatches `TELEPORT_REQUEST` with\\n`{ nodeName = <Node> }`. The teleport itself is the server\'s decision \u2014\\nthis only asks.\\n\\n### Guards\\n\\n* Touches from other players are ignored; only `Players.LocalPlayer`\\n  triggers a request.\\n* A one-second per-player cooldown suppresses the repeated `Touched`\\n  events a character generates while standing on the pad, so a single\\n  step is a single request.\\n* A pad with no `Node` attribute asserts at registration rather than\\n  silently doing nothing.\\n\\n:::note\\nThe `cooldown` table is keyed by `Player` even though only the local\\nplayer can ever get in \u2014 a leftover from the shared-code shape. Neither\\nthe cooldown nor the touch connection is torn down on\\n`CollectionObject.Destroyed`; pads live for the session.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","realm":["Client"],"source":{"line":35,"path":"src/Client/Features/CollectionWatcher/Watchers/TeleportPad.luau"}}')}}]);